rows as (
  select r.title, r.slug, r.excerpt, r.content, r.status, r.published_at, r.cover_image_url, r.cover_image_alt, r.seo_title, r.seo_description, r.canonical_url, r.focus_keyword, r.category, r.robots_meta, r.og_title, r.og_description, r.cta_type, r.search_intent, r.last_reviewed_at, r.next_review_at, r.tags, r.faqs, r.author_name
  from payload p
  cross join lateral jsonb_populate_record(null::public.web, p.doc) as r
),
updated as (
  update public.web as w
  set
  title = r.title,
  excerpt = r.excerpt,
  content = r.content,
  status = r.status,
  published_at = r.published_at,
  cover_image_url = r.cover_image_url,
  cover_image_alt = r.cover_image_alt,
  seo_title = r.seo_title,
  seo_description = r.seo_description,
  canonical_url = r.canonical_url,
  focus_keyword = r.focus_keyword,
  category = r.category,
  robots_meta = r.robots_meta,
  og_title = r.og_title,
  og_description = r.og_description,
  cta_type = r.cta_type,
  search_intent = r.search_intent,
  last_reviewed_at = r.last_reviewed_at,
  next_review_at = r.next_review_at,
  tags = r.tags,
  faqs = r.faqs,
  author_name = r.author_name
  from rows r
  where w.slug = r.slug
  returning w.slug
)
insert into public.web (title, slug, excerpt, content, status, published_at, cover_image_url, cover_image_alt, seo_title, seo_description, canonical_url, focus_keyword, category, robots_meta, og_title, og_description, cta_type, search_intent, last_reviewed_at, next_review_at, tags, faqs, author_name)
select r.title, r.slug, r.excerpt, r.content, r.status, r.published_at, r.cover_image_url, r.cover_image_alt, r.seo_title, r.seo_description, r.canonical_url, r.focus_keyword, r.category, r.robots_meta, r.og_title, r.og_description, r.cta_type, r.search_intent, r.last_reviewed_at, r.next_review_at, r.tags, r.faqs, r.author_name
from rows r
where not exists (select 1 from updated u where u.slug = r.slug);

